 * Turns an alignment into a list of changes: stretches of the base document
 * replaced by stretches of the other document. baseStart/baseEnd are
 * indices into base (end exclusive); lines are the other document's lines
 * for that stretch.
 */
export function changesFromMatches(base, other, matches) {
  const changes = []
  let bi = 0
  let oj = 0
  for (const [mi, mj] of matches) {
    if (mi > bi || mj > oj) {
      changes.push({ baseStart: bi, baseEnd: mi, lines: other.slice(oj, mj) })
    }
    bi = mi + 1
    oj = mj + 1
  }
  if (bi < base.length || oj < other.length) {
    changes.push({ baseStart: bi, baseEnd: base.length, lines: other.slice(oj, other.length) })
  }
  return changes
}

export function computeChanges(base, other) {
  return changesFromMatches(base, other, align(base, other))
}
