  const tagged = []
  for (const c of mineChanges) tagged.push({ ...c, side: 'mine' })
  for (const c of theirsChanges) tagged.push({ ...c, side: 'theirs' })
  tagged.sort((a, b) => a.baseStart - b.baseStart)

  const regions = []
  let idx = 0
  while (idx < tagged.length) {
    let baseStart = tagged[idx].baseStart
    let baseEnd = tagged[idx].baseEnd
    const group = [tagged[idx]]
    idx++
    while (idx < tagged.length && tagged[idx].baseStart <= baseEnd) {
      if (tagged[idx].baseEnd > baseEnd) baseEnd = tagged[idx].baseEnd
      group.push(tagged[idx])
      idx++
    }
    regions.push({ baseStart, baseEnd, changes: group })
  }
  return regions
