  const own = region.changes.filter(c => c.side === side).sort((a, b) => a.baseStart - b.baseStart)
  if (own.length === 0) return base.slice(region.baseStart, region.baseEnd)
  const lines = []
  let cursor = region.baseStart
  for (const c of own) {
    lines.push(...base.slice(cursor, c.baseStart))
    lines.push(...c.lines)
    cursor = c.baseEnd
  }
  lines.push(...base.slice(cursor, region.baseEnd))
  return lines
}

function resolveRegion(region, base) {
  const mine = sideLines(region, base, 'mine')
  const theirs = sideLines(region, base, 'theirs')
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  if (arraysEqual(mine, theirs)) return { type: 'both', mine, base: baseLines, theirs }
  if (arraysEqual(mine, baseLines)) return { type: 'theirs', mine, base: baseLines, theirs }
  if (arraysEqual(theirs, baseLines)) return { type: 'mine', mine, base: baseLines, theirs }
  return { type: 'conflict', mine, base: baseLines, theirs }
}

/**
 * Computes the ordered list of segments (stable stretches and resolved
 * regions) that together cover the whole base document.
 */
export function buildSegments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine)
  const theirsChanges = computeChanges(base, theirs)
  const regions = buildRegions(mineChanges, theirsChanges)

